/*Collect the unicode lists and glyph_id offsets*/
// 字符查找表
// 作用是 把 Unicode 编码 快速映射 到 字体点阵数据（glyph）上
 const txt_cmap_t cmaps[] =
{
    {
        .range_start = 32, // 从哪个 Unicode 编码开始
        .range_length = 95, //连续多少字符
        .glyph_id_start = 1, // 对应glyph数组的起始位置
        .unicode_list = NULL,  // unicode字符列表, NULL时为按照unicode连续存放，可随机存取；否则为未按照unicode连续存放，是分散存放的，需要顺序查找返回地址。
        // 字形偏移列表
        .list_length = 0// 列表长度
        // 映射表类型：LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY 适用于连续的字符范围
    },
    {
        .range_start = 12288, .range_length = 4, .glyph_id_start = 96,
        .unicode_list = NULL, .list_length = 0
    },
    {
        .range_start = 12293, .range_length = 19, .glyph_id_start = 100,
        .unicode_list = NULL, .list_length = 0
    },
    {
        .range_start = 12317, .range_length = 23811, .glyph_id_start = 119,
        .unicode_list = unicode_list_3, .list_length = 2975
        // 映射表类型：LV_FONT_FMT_TXT_CMAP_SPARSE_TINY 用于不连续的字符
    },
    {
        .range_start = 36129, .range_length = 17, .glyph_id_start = 3094,
        .unicode_list = NULL, .list_length = 0
    },
    {
        .range_start = 36148, .range_length = 4716, .glyph_id_start = 3111,
        .unicode_list = unicode_list_5, .list_length = 520
    }
};


// 串口打印字形信息
void get_glyph_dsc_info(uint32_t glyph_dsc_index){
	ESP_LOGI(TAG,"glyph_dsc_index:%lu {.bitmap_index =%lu, .adv_w =%lu, .box_w =%u, .box_h =%u, .ofs_x =%d, .ofs_y =%d}",
				glyph_dsc_index,
				glyph_dsc[glyph_dsc_index].bitmap_index, 
				glyph_dsc[glyph_dsc_index].adv_w, 
				glyph_dsc[glyph_dsc_index].box_w, 
				glyph_dsc[glyph_dsc_index].box_h, 
				glyph_dsc[glyph_dsc_index].ofs_x, 
				glyph_dsc[glyph_dsc_index].ofs_y);
}

void get_txt_cmap_t_info(uint8_t cmaps_index){
  ESP_LOGI(TAG,"当前txt_cmap_index:%d",cmaps_index);
	ESP_LOGI(TAG,".range_start =%lu,.range_length =%lu,.glyph_id_start =%lu,.unicode_list = %d,.list_length = %lu",
          cmaps[cmaps_index].range_start,
          cmaps[cmaps_index].range_length,
          cmaps[cmaps_index].glyph_id_start,
          cmaps[cmaps_index].unicode_list,
          cmaps[cmaps_index].list_length);
}
